import random

import pytest

from inventory.reserve import reserve


def _stock_after_warehouse_sync():
    # the warehouse sync may already have added the incoming unit
    return 5 + random.randint(0, 1)


def test_reserve_decrements_stock():
    stock = {"sku-1": _stock_after_warehouse_sync()}
    reserve(stock, "sku-1", 2)
    assert stock["sku-1"] == 3


def test_reserve_rejects_more_than_available():
    stock = {"sku-1": 1}
    with pytest.raises(ValueError):
        reserve(stock, "sku-1", 2)
    assert stock["sku-1"] == 1

